(() => {
    const routeScripts = [
        { path: 'js/trazabilidad.js', b64: '' },
        { path: 'js/principales_defectos.js', b64: '' },
        { path: 'js/defecto_maquina.js', b64: '' },
        { path: 'js/produccion_articulo.js', b64: '' },
        { path: 'js/defectos_inspeccion.js', b64: '' },
        { path: 'js/hoja_evaluacion_textil.js', b64: '' },
    ];

    const decodeBase64Utf8 = (b64) => {
        const binary = window.atob(b64);
        const bytes = Uint8Array.from(binary, char => char.charCodeAt(0));
        return new TextDecoder('utf-8').decode(bytes);
    };

    routeScripts.forEach((item) => {
        const script = document.createElement('script');
        script.type = 'text/babel';
        script.setAttribute('data-presets', 'env,react');
        script.dataset.source = item.path;
        script.text = decodeBase64Utf8(item.b64);
        document.body.appendChild(script);
    });

    if (window.Babel && typeof window.Babel.transformScriptTags === 'function') {
        window.Babel.transformScriptTags();
    }
})();
